package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.proteomics.MaxLfq;
import static org.jlinalg.cli.IqRequest.require;
import static org.jlinalg.cli.NextflowFiles.*;

/** Complete literal input rows, source duplicate aggregation, protein/sample populations and replay. */
final class IqCompute {
    private IqCompute() { }
    static Map<String,Object> map(Object... entries) { var result=new LinkedHashMap<String,Object>(); for(int i=0;i<entries.length;i+=2)result.put((String)entries[i],entries[i+1]); return result; }
    static final class Budget { final long maximum; long bytes; Budget(long max){maximum=max;} void add(int amount)throws IOException{require(amount<=maximum-bytes,"Complete iq generated bytes exceed output_bytes; no truncation");bytes+=amount;} }
    static final class Sink implements AutoCloseable {
        final OutputStream output; final InputStream expected; final Budget budget; final Runnable check;
        Sink(Path path,boolean replay,Budget budget,Runnable check)throws IOException { this.budget=budget;this.check=check;output=replay?null:Files.newOutputStream(path,StandardOpenOption.CREATE_NEW);expected=replay?Files.newInputStream(path,LinkOption.NOFOLLOW_LINKS):null; }
        void line(String value)throws IOException {check.run();byte[] raw=(value+"\n").getBytes(StandardCharsets.UTF_8);budget.add(raw.length);if(output!=null)output.write(raw);else require(Arrays.equals(raw,expected.readNBytes(raw.length)),"Saved iq row/value differs from complete numerical replay");}
        @Override public void close()throws IOException {if(output!=null)output.close();else {try{require(expected.read()==-1,"Saved iq output has extra bytes/rows");}finally{expected.close();}}}
    }
    static Map<String,Object> run(Path root,IqRequest.Spec spec,boolean replay,Runnable check)throws IOException {
        var capacity=spec.capacity();var observations=new ArrayList<MaxLfq.Observation>();var proteins=new LinkedHashSet<String>();var samples=new LinkedHashSet<String>();var cells=new HashMap<List<String>,Integer>();
        long identifierBytes=0;var budget=new Budget(capacity.outputBytes());var decoded=new MetaxcanTable.Budget(capacity.decodedBytes(),check);
        try(var rows=new Sink(root.resolve("ROWS.jsonl"),replay,budget,check);var input=new MetaxcanTable(root.resolve("inputs/ions.table"),spec.gzip(),spec.separator(),capacity.rows(),decoded,true)) {
            var indices=new LinkedHashMap<String,Integer>();for(var entry:spec.columns().entrySet())indices.put(entry.getKey(),input.column(entry.getValue()));
            for(List<String> row;(row=input.next())!=null;) {
                check.run();String protein=row.get(indices.get("protein")),sample=row.get(indices.get("sample")),ion=row.get(indices.get("ion")),value=row.get(indices.get("quant"));double quant;
                require(value.equals(value.strip()) && !value.isEmpty(),"Finite literal normalized log2 quantity required; no whitespace/value repair");
                try{quant=Double.parseDouble(value);}catch(NumberFormatException error){throw new IOException("Non-numeric iq quantity at input row "+input.rows()+"; missing rows are not silently removed",error);}
                MaxLfq.Observation observation;
                try{observation=new MaxLfq.Observation(protein,sample,ion,quant);}catch(IllegalArgumentException error){throw new IOException("Invalid iq observation at input row "+input.rows()+": "+error.getMessage(),error);}
                proteins.add(protein);samples.add(sample);require(proteins.size()<=capacity.proteins()&&samples.size()<=capacity.samples(),"Complete iq protein/sample capacity exceeded");
                identifierBytes=Math.addExact(identifierBytes,Math.addExact(512L,4L*(protein.length()+sample.length()+ion.length())));
                require(identifierBytes<=capacity.numericBytes(),"Complete iq observation/identifier memory estimate exceeds numeric_bytes; increase capacity and JVM heap or use a separately qualified streaming workflow");
                observations.add(observation);var key=List.of(protein,sample,ion);int duplicate=cells.merge(key,1,Math::addExact);var source=new LinkedHashMap<String,String>();for(int i=0;i<input.header().size();i++)source.put(input.header().get(i),row.get(i));
                rows.line(NextflowJson.json(map("ordinal",input.rows(),"protein",protein,"sample",sample,"ion",ion,"normalized_log2",quant,"cell_observation",duplicate,"status",duplicate==1?"USED_FIRST_OBSERVATION":"SOURCE_SUM_IN_LINEAR_SPACE","source_cells",source)));
            }
            require(input.complete(),"Incomplete iq ion table");
        }catch(IOException error){throw new IOException(error.getMessage().replace("MetaXcan","iq"),error);}
        require(!observations.isEmpty(),"No quantitative input observations; no protein result admitted");
        // Reserve the retained complete row/identifier population before numerical work.
        var requested=capacity.limits();long available=capacity.numericBytes()-identifierBytes;require(available>0,"No declared numerical memory remains after complete iq input capture");
        var limits=new MaxLfq.Limits(requested.samples(),requested.ions(),requested.cells(),requested.pairComparisons(),available,requested.work(),requested.iterations());
        MaxLfq.Table table=MaxLfq.fast(observations,limits,check);require(table.proteins().size()==proteins.size()&&table.samples().equals(List.copyOf(samples)),"Native iq identity/population differs");
        long observed=0,missing=0,ratios=0;int maxIterations=0;double maxResidual=0;
        try(var output=new Sink(root.resolve("outputs/proteins.tsv"),replay,budget,check);var audit=new Sink(root.resolve("PROTEINS.jsonl"),replay,budget,check);var population=new Sink(root.resolve("SAMPLES.jsonl"),replay,budget,check)) {
            output.line("protein\tsample\tnormalized_log2\tcomponent_zero_based\tsource_annotation");
            for(int i=0;i<table.samples().size();i++)population.line(NextflowJson.json(map("ordinal",i+1,"sample",table.samples().get(i),"source_order","first-observed")));
            int ordinal=0;
            for(var protein:table.proteins()) {
                var r=protein.result();var estimates=r.estimate();var labels=r.component();var values=new ArrayList<Object>();
                for(int i=0;i<estimates.length;i++){double estimate=estimates[i];String number;if(Double.isNaN(estimate)){missing++;values.add(null);number="NA";}else{require(Double.isFinite(estimate),"Nonfinite iq estimate; no result admitted");observed++;values.add(estimate);number=Double.toString(estimate);}output.line(protein.id()+"\t"+table.samples().get(i)+"\t"+number+"\t"+labels[i]+"\t"+r.annotation());}
                var components=new ArrayList<Integer>();for(int c:labels)components.add(c);
                audit.line(NextflowJson.json(map("ordinal",++ordinal,"protein",protein.id(),"ions",protein.ions(),"input_rows",protein.inputRows(),"duplicate_rows",protein.duplicateRows(),"estimate",values,"component_zero_based",components,"source_annotation",r.annotation(),"observed_cells",r.observedCells(),"pairwise_ratios",r.ratios(),"iterations",r.iterations(),"relative_residual",r.relativeResidual(),"cumulative_work",r.work())));
                ratios=Math.addExact(ratios,r.ratios());maxIterations=Math.max(maxIterations,r.iterations());maxResidual=Math.max(maxResidual,r.relativeResidual());
            }
        }
        require(observed>0,"No finite protein quantity; no complete iq result admitted");
        return map("schema_version",1,"engine","native","source_edition","iq-2.3.0","mode","fast-maxlfq","units","already-normalized-log2","input_rows",table.inputRows(),"proteins",table.proteins().size(),"samples",table.samples().size(),"duplicate_rows",table.duplicateRows(),"observed_protein_sample_quantities",observed,"missing_protein_sample_quantities",missing,"pairwise_ratios",ratios,"maximum_iterations",maxIterations,"maximum_relative_residual",maxResidual,"numeric_work",table.work(),"decoded_bytes",decoded.decoded,"generated_data_bytes",budget.bytes,"retained_row_memory_estimate",identifierBytes,"normalization_performed",false,"original_R_executable_run",false,"whole_paper_reproduced",false);
    }
}
